mapper.select:
SELECT TOP 1 center_code
FROM erp_student
WHERE student_id = #{studentId}

SELECT TOP 1 grade_key
FROM erp_student
WHERE student_id = #{studentId}

SELECT TOP 1 clinic_grade_key
FROM erp_student
WHERE student_id = #{studentId}

mapper.update:
UPDATE erp_student
SET clinic_grade_key = #{schoolyear}
WHERE student_id = #{studentId}

mapper.select:
SELECT COUNT(*)
FROM erp_bookstore_recommend_log
WHERE student_id = #{studentId}
  AND CAST(recommended_at AS DATE) = #{date}

mapper.update:
UPDATE erp_bookstore_recommend_log
SET final_correct_count = #{finalCorrectCount},
    grade               = #{grade}
WHERE recommend_id = #{recommendId}

mapper.select:
SELECT COUNT(*)
FROM erp_bookstore_recommend_log rl
JOIN erp_bookstore_content c ON c.content_id = rl.content_id
WHERE rl.student_id = #{studentId}
  AND rl.status = 'DONE'
  AND c.schoolyear = #{schoolyear}

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM erp_bookstore_student_card
    WHERE student_id = #{studentId} AND card_type = 'RARE' AND trigger_count = #{triggerCount}
) THEN 1 ELSE 0 END

SELECT title
FROM erp_bookstore_level
WHERE schoolyear = #{schoolyear} AND level_no = #{levelNo}

SELECT TOP 1 b.badge_id AS badgeId, b.badge_name AS badgeName, b.badge_desc AS badgeDesc, b.category AS category, b.threshold AS threshold, b.param AS param FROM erp_bookstore_student_badge sb JOIN erp_bookstore_badge b ON b.badge_id = sb.badge_id WHERE sb.student_id = #{studentId} AND sb.content_id = #{contentId}
AND sb.badge_id IN (3, 4) AND sb.badge_id IN (1, 2)
ORDER BY b.badge_id DESC

SELECT COUNT(*)
FROM erp_bookstore_quiz_answer_log
WHERE student_id = #{studentId} AND content_id = #{contentId} AND qlevel = #{qlevel}

SELECT COUNT(DISTINCT submitted_at)
FROM erp_bookstore_quiz_answer_log
WHERE recommend_id = #{recommendId} AND qlevel = #{qlevel}

mapper.update:
UPDATE erp_bookstore_recommend_log
   SET hold_page = #{holdPage}
 WHERE student_id = #{studentId}
   AND (status = 'PENDING' OR (status = 'HOLD' AND hold_use = 'Y'))
